package org.humanjourney.core.geography.map;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.humanjourney.core.geography.*;
import org.humanjourney.core.npc.context.NpcGeography;
import org.humanjourney.core.water.*;

class MapGeometryTest {
 static final String DIM="minecraft:overworld";
 static List<WaterGeography.Point> square(double x,double z,double size){return List.of(new WaterGeography.Point(x,z),new WaterGeography.Point(x+size,z),new WaterGeography.Point(x+size,z+size),new WaterGeography.Point(x,z+size));}
 static MapArea area(MapArea.Kind k,String id,int priority,String parent,double x,double size){return MapArea.decoded(k,id,"Label "+id,DIM,priority,parent,square(x,0,size));}
 static NpcGeography.Area nativeArea(String id,int priority,String parent,Map<String,String> labels,double size){return new NpcGeography.Area(id,DIM,priority,parent,"Label "+id,labels,new WaterGeography.Region(id,DIM,WaterPolicy.Quality.NORMAL,square(0,0,size)),null);}
 static Map<MapArea.Key,MapArea> areas(MapArea... values){var out=new TreeMap<MapArea.Key,MapArea>();for(var a:values)out.put(a.key(),a);return out;}
 static final UUID SESSION=UUID.fromString("00000000-0000-0000-0000-000000000011");
 static MapPackets.Header header(long sequence){return new MapPackets.Header(SESSION,sequence,sequence,sequence,sequence);}
 static List<MapPackets.Frame> full(long sequence,Collection<MapArea> values){return MapPackets.frames(header(sequence),MapPackets.Mode.FULL,0,values,List.of());}
 static void apply(ClientMapState c,List<MapPackets.Frame> frames){frames.forEach(c::accept);}
 @Test void projectionContainsOnlyDiscoveredWithNoUndiscoveredParentLeak(){var geo=new NpcGeography(List.of(nativeArea("macro",0,"none",Map.of(),100),nativeArea("secret",1,"none",Map.of(),200)),List.of(nativeArea("local",0,"secret",Map.of(),20)));var v=new MapProjection.Factory(geo,"era_test").project(new DiscoveryLedger.Snapshot(Set.of("macro","stale"),Set.of("local","removed"),3));assertEquals(2,v.areas().size());assertEquals(1,v.staleMacros());assertEquals(1,v.staleLocals());assertFalse(v.areas().containsKey(new MapArea.Key(MapArea.Kind.MACRO,"secret")));assertEquals("",v.areas().get(new MapArea.Key(MapArea.Kind.LOCAL,"local")).parent());}
 @Test void discoveredParentAndEraLabelsAreProjected(){var geo=new NpcGeography(List.of(nativeArea("macro",0,"none",Map.of("era_test","Historical"),100)),List.of(nativeArea("local",0,"macro",Map.of(),20)));var s=new DiscoveryLedger.Snapshot(Set.of("macro"),Set.of("local"),1);var v=new MapProjection.Factory(geo,"era_test").project(s);assertEquals("Historical",v.areas().get(new MapArea.Key(MapArea.Kind.MACRO,"macro")).label());assertEquals("macro",v.areas().get(new MapArea.Key(MapArea.Kind.LOCAL,"local")).parent());assertNotEquals(v,new MapProjection.Factory(geo,"other_era").project(s));}
 @Test void higherDiscoveredLocalWinsAndHiddenLocalDoesNotExist(){var broad=area(MapArea.Kind.LOCAL,"broad",0,"",0,100);var high=area(MapArea.Kind.LOCAL,"specific",10,"",0,20);var c=new ClientMapState();apply(c,full(1,List.of(broad)));assertEquals(broad.label(),c.snapshot().index().hover(DIM,5,5).primary());apply(c,MapPackets.frames(header(2),MapPackets.Mode.DELTA,1,List.of(high),List.of()));assertEquals(high.label(),c.snapshot().index().hover(DIM,5,5).primary());}
 @Test void parentWinsOverIndependentMacroWhenDiscovered(){var parent=area(MapArea.Kind.MACRO,"parent",0,"",100,20);var other=area(MapArea.Kind.MACRO,"other",100,"",0,100);var local=area(MapArea.Kind.LOCAL,"local",0,"parent",0,20);var index=new MapSpatialIndex(areas(parent,other,local));assertEquals(parent.label(),index.hover(DIM,5,5).secondary());}
 @Test void redactedParentUsesIndependentMacroAndLocalOnlyIsValid(){var local=area(MapArea.Kind.LOCAL,"local",0,"",0,20);var macro=area(MapArea.Kind.MACRO,"macro",0,"",0,100);assertEquals(macro.label(),new MapSpatialIndex(areas(local,macro)).hover(DIM,5,5).secondary());assertEquals("",new MapSpatialIndex(areas(local)).hover(DIM,5,5).secondary());}
 @Test void macroOnlyWrongDimensionOutsideAndInvalidPoint(){var macro=area(MapArea.Kind.MACRO,"macro",0,"",0,100);var index=new MapSpatialIndex(areas(macro));assertEquals(macro.label(),index.hover(DIM,50,50).primary());assertFalse(index.hover("minecraft:the_nether",50,50).visible());assertFalse(index.hover(DIM,200,200).visible());assertFalse(index.hover(DIM,Double.NaN,0).visible());}
 @Test void boundaryMatchesNativeContainmentExactly(){var a=area(MapArea.Kind.LOCAL,"local",0,"",0,20);var index=new MapSpatialIndex(areas(a));for(double x:new double[]{-1,0,1,20,21})for(double z:new double[]{-1,0,1,20,21})assertEquals(a.shape().contains(x,z),index.hover(DIM,x,z).visible(),x+","+z);}
 @Test void equalPriorityAmbiguityFailsClosed(){var index=new MapSpatialIndex(areas(area(MapArea.Kind.LOCAL,"one",1,"",0,20),area(MapArea.Kind.LOCAL,"two",1,"",0,20)));assertTrue(index.hover(DIM,5,5).ambiguous());assertFalse(index.hover(DIM,5,5).visible());}
 @Test void multipartSnapshotIsAtomicAndInterruptedTransferKeepsOld(){var c=new ClientMapState();var old=area(MapArea.Kind.LOCAL,"old",0,"",0,20);apply(c,full(1,List.of(old)));var entries=new ArrayList<MapArea>();for(int i=0;i<20;i++)entries.add(area(MapArea.Kind.LOCAL,"area_"+i,0,"",i*100,20));var frames=full(2,entries);assertEquals(3,frames.size());assertFalse(c.accept(frames.get(2)));assertEquals(areas(old),c.snapshot().areas());assertFalse(c.accept(frames.get(0)));assertEquals(areas(old),c.snapshot().areas());assertTrue(c.accept(frames.get(1)));assertEquals(20,c.snapshot().areas().size());}
 @Test void staleSnapshotsDeltasAndComponentRegressionsCannotOverwrite(){var c=new ClientMapState();var a=area(MapArea.Kind.LOCAL,"current",0,"",0,20);apply(c,full(10,List.of(a)));apply(c,full(1,List.of()));apply(c,MapPackets.frames(header(9),MapPackets.Mode.DELTA,8,List.of(),List.of(a.key())));var lowerData=new MapPackets.Header(SESSION,11,11,1,11);apply(c,MapPackets.frames(lowerData,MapPackets.Mode.FULL,0,List.of(),List.of()));assertEquals(areas(a),c.snapshot().areas());}
 @Test void futureDeltaWaitsForExactBaseAndThenApplies(){var c=new ClientMapState();apply(c,full(1,List.of()));var a=area(MapArea.Kind.LOCAL,"first",0,"",0,20);var b=area(MapArea.Kind.LOCAL,"second",0,"",100,20);apply(c,MapPackets.frames(header(3),MapPackets.Mode.DELTA,2,List.of(b),List.of()));assertTrue(c.needsResync());apply(c,MapPackets.frames(header(2),MapPackets.Mode.DELTA,1,List.of(a),List.of()));assertEquals(areas(a,b),c.snapshot().areas());assertFalse(c.needsResync());}
 @Test void clearDefeatsDelayedSnapshotAndRoleRevocationHidesEverything(){var c=new ClientMapState();var a=area(MapArea.Kind.LOCAL,"local",0,"",0,20);apply(c,full(1,List.of(a)));apply(c,MapPackets.frames(header(3),MapPackets.Mode.CLEAR,0,List.of(),List.of()));apply(c,full(2,List.of(a)));assertTrue(c.snapshot().areas().isEmpty());apply(c,full(4,List.of(a)));c.role(false);assertTrue(c.snapshot().areas().isEmpty());apply(c,full(5,List.of(a)));assertTrue(c.snapshot().areas().isEmpty());c.role(true);assertTrue(c.needsResync());apply(c,full(6,List.of(a)));assertEquals(areas(a),c.snapshot().areas());}
 @Test void reconnectRequiresNewConnectionStateThenAcceptsNewSession(){var c=new ClientMapState();apply(c,full(10,List.of()));var h=new MapPackets.Header(UUID.randomUUID(),1,1,1,1);var frames=MapPackets.frames(h,MapPackets.Mode.FULL,0,List.of(area(MapArea.Kind.LOCAL,"new",0,"",0,20)),List.of());apply(c,frames);assertTrue(c.snapshot().areas().isEmpty());c.clear();apply(c,frames);assertEquals(1,c.snapshot().areas().size());}
 @Test void malformedAndInvalidParentKeepLastValidState(){var c=new ClientMapState();var a=area(MapArea.Kind.LOCAL,"old",0,"",0,20);apply(c,full(1,List.of(a)));assertFalse(c.accept(MapPackets.Frame.bad("bad geometry")));apply(c,full(2,List.of(area(MapArea.Kind.LOCAL,"new",0,"undiscovered",0,20))));assertEquals(areas(a),c.snapshot().areas());assertTrue(c.needsResync());}
 @Test void sourceReloadReplacementRemovesOldGeometryAndChangesVertices(){var c=new ClientMapState();apply(c,full(1,List.of(area(MapArea.Kind.LOCAL,"keep",0,"",0,20),area(MapArea.Kind.LOCAL,"removed",0,"",0,20))));apply(c,full(2,List.of(area(MapArea.Kind.LOCAL,"keep",10,"",100,20))));assertEquals(1,c.snapshot().areas().size());assertFalse(c.snapshot().index().hover(DIM,5,5).visible());assertTrue(c.snapshot().index().hover(DIM,110,10).visible());}
 @Test void duplicatePartsAreIdempotentButConflictingPartsAreRejected(){var entries=new ArrayList<MapArea>();for(int i=0;i<9;i++)entries.add(area(MapArea.Kind.LOCAL,"a_"+i,0,"",i*100,20));var frames=full(1,entries);var c=new ClientMapState();c.accept(frames.get(0));c.accept(frames.get(0));assertFalse(c.needsResync());var conflict=new MapPackets.Frame(header(1),MapPackets.Mode.FULL,0,0,2,List.of(),List.of(),null);assertFalse(c.accept(conflict));assertTrue(c.needsResync());assertTrue(c.snapshot().areas().isEmpty());}
 @Test void fullScaleCatalogUsesBoundedFramesAndIndexedCandidates(){var entries=new ArrayList<MapArea>();for(int i=0;i<512;i++)entries.add(area(MapArea.Kind.MACRO,"m_"+i,0,"",i*100,20));for(int i=0;i<4096;i++)entries.add(area(MapArea.Kind.LOCAL,"l_"+i,0,"",i*100,20));var frames=full(1,entries);assertEquals(576,frames.size());assertTrue(frames.stream().allMatch(f->f.areas().size()<=8));var c=new ClientMapState();apply(c,frames);assertEquals(4608,c.snapshot().areas().size());var hover=c.snapshot().index().hover(DIM,5,5);assertEquals(2,hover.candidates());assertEquals(1,c.snapshot().index().query(DIM,MapArea.Kind.LOCAL,new MapArea.Bounds(0,0,20,20)).size());}
 @Test void cameraRoundTripUsesRawPixelsAcrossPanZoomAndGuiScales(){for(double scale:new double[]{.02,1,128})for(double gui:new double[]{1,2,3.5}){var t=new MapViewTransform(1921,1081,gui,3404,-2758,scale);var screen=t.screen(3500,-3000);var world=t.world(screen.x(),screen.y());assertEquals(3500,world.x(),1e-8);assertEquals(-3000,world.y(),1e-8);assertEquals(Math.floor(1921/2D)/gui,t.screen(3404,-2758).x(),1e-8);}}
 @Test void worldSegmentClippingDoesNotModifyAuthoritativeGeometry(){var t=new MapViewTransform(100,100,1,0,0,1);var v=t.viewport(100,100);var line=t.segment(-1000,0,1000,0,v);assertNotNull(line);assertEquals(0,line.a().x(),1e-8);assertEquals(100,line.b().x(),1e-8);assertNull(t.segment(-1000,200,1000,200,v));}
 @Test void geometryMetadataValidationRejectsInvalidInput(){assertThrows(IllegalArgumentException.class,()->MapArea.decoded(MapArea.Kind.LOCAL,"ok","",DIM,0,"",square(0,0,20)));assertThrows(IllegalArgumentException.class,()->MapArea.decoded(MapArea.Kind.LOCAL,"ok","Name",DIM,0,"",List.of(new WaterGeography.Point(0,0))));assertThrows(IllegalArgumentException.class,()->new MapViewTransform(100,100,1,0,0,0));}
}
